    string error_msg = "Status: " + std::to_string(e.status) +
                       ", message: " + std::string(e.message) + ", in file " +
                       std::string(__FILE__) + ":" + std::to_string(__LINE__);
    OP_REQUIRES_OK(
        ctx, errors::Aborted("Operation received an exception:", error_msg));
  }
}

